#include "../ert-cuda/kernel.h"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <vector>
#include <chrono>
#include <string>
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(3);}}while(0)
std::vector<double>load(std::string f){std::ifstream s(f,std::ios::binary|std::ios::ate);size_t n=s.tellg();s.seekg(0);std::vector<double>x(n/8);s.read((char*)x.data(),n);return x;}
struct Case{int ty,n,t,b,h,lanes;void*base;std::vector<double>initial;};
std::vector<double>fetch(Case&c){std::vector<double>out;size_t z=c.n+16;if(c.ty==1){std::vector<half2>h(z);CK(cudaMemcpy(h.data(),c.base,z*sizeof(half2),cudaMemcpyDeviceToHost));for(auto v:h){float2 p=__half22float2(v);out.push_back(p.x);out.push_back(p.y);}}else if(c.ty==2){std::vector<float>h(z);CK(cudaMemcpy(h.data(),c.base,z*4,cudaMemcpyDeviceToHost));out.assign(h.begin(),h.end());}else{out.resize(z);CK(cudaMemcpy(out.data(),c.base,z*8,cudaMemcpyDeviceToHost));}return out;}
void reset(Case&c){size_t z=c.n+16;if(c.ty==1){std::vector<half2>h(z);for(size_t i=0;i<z;i++)h[i]=__floats2half2_rn(c.initial[i*2],c.initial[i*2+1]);CK(cudaMemcpy(c.base,h.data(),z*4,cudaMemcpyHostToDevice));}else if(c.ty==2){std::vector<float>h(c.initial.begin(),c.initial.end());CK(cudaMemcpy(c.base,h.data(),z*4,cudaMemcpyHostToDevice));}else CK(cudaMemcpy(c.base,c.initial.data(),z*8,cudaMemcpyHostToDevice));}
void launch(Case&c){if(c.ty==1)block_stride<half2><<<c.b,c.h>>>(c.t,c.n,(half2*)c.base+8);else if(c.ty==2)block_stride<float><<<c.b,c.h>>>(c.t,c.n,(float*)c.base+8);else block_stride<double><<<c.b,c.h>>>(c.t,c.n,(double*)c.base+8);CK(cudaDeviceSynchronize());}
int main(){std::string root=std::string(__FILE__).substr(0,std::string(__FILE__).find_last_of('/'));auto fixture=load(root+"/fixture.bin"),gold=load(root+"/oracle.bin");std::vector<Case>cases;size_t pos=0;for(int k=0;k<12;k++){Case c;c.ty=fixture[pos++];c.n=fixture[pos++];c.t=fixture[pos++];c.b=fixture[pos++];c.h=fixture[pos++];c.lanes=c.ty==1?2:1;c.initial.assign((c.n+16)*c.lanes,-777);for(int j=0;j<c.n*c.lanes;j++)c.initial[8*c.lanes+j]=fixture[pos++];CK(cudaMalloc(&c.base,(c.n+16)*(c.ty==3?8:4)));reset(c);launch(c);cases.push_back(c);}
 for(int trial=1;trial<=5;trial++){std::vector<double>prefix,out,echo,times;double elapsed=0;for(auto&c:cases){reset(c);CK(cudaDeviceSynchronize());auto actual=fetch(c);prefix.insert(prefix.end(),{double(c.ty),double(c.n),double(c.t),double(c.b),double(c.h)});prefix.insert(prefix.end(),actual.begin()+8*c.lanes,actual.end()-8*c.lanes);auto start=std::chrono::steady_clock::now();launch(c);double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();elapsed+=dt;times.push_back(dt);auto got=fetch(c);out.insert(out.end(),got.begin(),got.end());echo.insert(echo.end(),actual.begin(),actual.end());}
 bool ok=prefix.size()==fixture.size()&&memcmp(prefix.data(),fixture.data(),fixture.size()*8)==0&&out==gold;std::vector<double>values=prefix;values.insert(values.end(),out.begin(),out.end());values.insert(values.end(),echo.begin(),echo.end());std::string name="output_trial"+std::to_string(trial)+".bin";std::ofstream o(name,std::ios::binary);o.write((char*)values.data(),values.size()*8);o.close();std::cout<<std::setprecision(17)<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<values.size()<<",\"max_abs_error\":0,\"max_rel_error\":0,\"path_times_seconds\":[";for(size_t i=0;i<times.size();i++){if(i)std::cout<<",";std::cout<<times[i];}std::cout<<"],\"timing_region\":\"sum12_hostinclusive_freshstate_single_kernel_regions\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\""<<name<<"\",\"dtype\":\"float64\",\"count\":"<<values.size()<<",\"byte_order\":\"little\"}}\n";}
}
